// ------------------------------ Types ------------------------------

/** Props for the PlotTooltipContent component */
export interface PlotTooltipContentProps extends PlotTooltipBaseProps, JSX.HTMLAttributes<HTMLDivElement> {}

interface ConstructibleRowProps {
	constructible: PlotTooltipConstructibleInfo;
	showHeader?: boolean;
	isLocalPlayer: boolean;
}

interface SpecialistsRowProps {
	current: number;
	max: number;
}

interface PlayerOwnerRowProps {
	playerName: string;
	civName: string;
	isLocalPlayer: boolean;
	playerId: PlayerId;
	conquerorInfo?: { isIndependent: boolean; name: string };
	settlementName?: string;
}

interface IndependentUnitInfoProps {
	civName: string;
	relationship?: UnitOwnerRelationship;
}

interface PlayerUnitInfoProps {
	unit: Unit;

	ownerName: string;
	civName: string;
	relationship?: UnitOwnerRelationship;
	isAtWarWithOwner: boolean;
}

interface ResourceInfoRowProps {
	resource: ResourceDefinition;
	isDistantLands: boolean;
	showHeaderDivider?: boolean;
}

interface DebugInfoSectionProps {
	plotCoord: float2;
	plotIndex: number;
	currentHealth?: number;
	maxHealth?: number;
}

interface FreeImprovementInfo {
	name: string;
	icon: string;
	type: string;
}

interface ConstructibleRowsProps {
	constructibles: PlotTooltipConstructibleInfo[];
	district: District | null;
	freeImprovement: FreeImprovementInfo | null;
	showTopDivider?: boolean;
	isLocalPlayer: boolean;
}

interface PlotDetailsSectionProps {
	/** The X,Y coordinates of the plot */
	plotCoord: float2;

	/** The player that owns this plot */
	owningPlayer: PlayerId;
	/** The city that owns this plot, or null if unowned. */
	owningCity: City | null;

	constructibles: PlotTooltipConstructibleInfo[];

	district: District | null;
}

// ------------------------------ Sub-Components ------------------------------

interface ConstructibleRowEntryIcon {
	icon: `url(${string})`;
	tooltipProps?: TooltipTextProps;
}

/** Constructible item display */
const ConstructibleRow: Component<ConstructibleRowProps> = (props) => {
	const statusEntryIcons = createMemo(() => {
		const entryIcons: ConstructibleRowEntryIcon[] = [];

		if (props.constructible.damaged) {
			entryIcons.push({ icon: "url(blp:fonticon_damaged)" });
		}

		if (props.constructible.overbuildable && props.isLocalPlayer) {
			entryIcons.push({
				icon: "url(blp:city_overbuildable)",
				tooltipProps: {
					header: "LOC_PLOT_TOOLTIP_OVERBUILDABLE",
					text: "LOC_PEDIA_CONCEPTS_OVERBUILDABLE_TOOLTIP",
				},
			});
		}

		return entryIcons;
	});

	return (
		<TicketRow
			icon={
				<Icon
					class="size-6"
					isUrl
					name={props.constructible.icon}
				/>
			}
		>
			<div class="flex flex-row gap-2">
				{/* TODO: Always use ProductionTooltip for constructibles once descriptions for improvements are written */}
				<Show
					when={!props.constructible.isImprovement}
					fallback={
						<L10n.Stylize
							class="font-title text-sm"
							text={props.constructible.title}
						/>
					}
				>
					<ProductionTooltip
						type={props.constructible.type}
						name={props.constructible.title}
						initialVPosition={TooltipVerticalPosition.BOTTOM}
						initialHPosition={TooltipHorizontalPosition.RIGHT}
						allowFlip
					>
						<TooltipKeyword>
							<L10n.Stylize
								class="font-title text-sm"
								text={props.constructible.title}
							/>
						</TooltipKeyword>
					</ProductionTooltip>
				</Show>
				<For each={statusEntryIcons()}>
					{(entry) => (
						<div class="flex items-center">
							<Show
								when={entry.tooltipProps}
								fallback={
									<Icon
										isUrl
										class="size-5"
										name={entry.icon}
									/>
								}
							>
								{(tooltipProps) => (
									<Tooltip.Text {...tooltipProps()}>
										<div use:isFocusable={[true, undefined]}>
											<Icon
												isUrl
												name={entry.icon}
												class="size-5"
											/>
										</div>
									</Tooltip.Text>
								)}
							</Show>
						</div>
					)}
				</For>
			</div>
			<Show when={props.constructible.isWonder && props.constructible.description}>
				{(description) => (
					<L10n.Stylize
						class="font-body text-sm text-accent-3"
						text={description()}
					/>
				)}
			</Show>
		</TicketRow>
	);
};

