/** Owner info section for regular players, with leader portrait. */
const PlayerOwnerRow: Component<PlayerOwnerRowProps> = (props) => {
	const displayName = createMemo(() => {
		if (props.isLocalPlayer) {
			return `{1_Name} ({LOC_PLOT_TOOLTIP_YOU})`;
		}
		return "{1_Name}";
	});

	return (
		<>
			<TicketRow
				class="text-sm"
				icon={
					<PlotTooltipPlayerPortrait
						leaderId={props.playerId}
						size={9}
					/>
				}
			>
				<Show when={props.settlementName}>
					{(settlementName) => (
						<L10n.Stylize
							class="font-title uppercase text-secondary"
							text={settlementName()}
						/>
					)}
				</Show>
				<L10n.Stylize
					class="font-title text-sm text-accent-2"
					text={displayName()}
					args={[props.civName]}
				/>
			</TicketRow>
			<Show when={props.conquerorInfo}>
				{(info) => (
					<Show
						when={info().isIndependent}
						fallback={
							<L10n.Stylize
								class="font-body text-sm text-accent-3"
								text="{1_Term}: {2_Subject}"
								args={["LOC_PLOT_TOOLTIP_CONQUEROR", info().name]}
							/>
						}
					>
						<L10n.Stylize
							class="font-body text-sm text-accent-3"
							text="{1_Term}: {2_Subject}"
							args={["LOC_PLOT_TOOLTIP_CONQUEROR", "LOC_PLOT_TOOLTIP_INDEPENDENT_CONQUEROR"]}
						/>
					</Show>
				)}
			</Show>
		</>
	);
};

/** Unit information section with banner-style background. */
const UnitInfoSection: Component<UnitInfoSectionProps> = (props) => {
	const flagColor = createMemo(() => {
		const pid = props.unit.owner;
		if (pid == null) return "";
		const playerColor = UI.Color.getPlayerColors(pid);
		if (!playerColor) return "";
		const variants = UI.Color.createPlayerColorVariants(playerColor);
		return variants.primaryColor.moreColor;
	});

	const unitTypeString = createMemo(() => GameInfo.Units.lookup(props.unit.type)?.UnitType);

	const unitIcon = () => (
		<UnitFlag
			color={flagColor()}
			unitIcon={props.unitIcon}
			// civSymbol={props.civSymbol}
		/>
	);

	return (
		<TicketSection
			name="UnitInfoSection"
			class="relative"
		>
			<div
				class="absolute top-0\.5 right-2\.5 size-7 flex items-center justify-center bg-contain bg-center bg-no-repeat"
				style={{ "background-image": "url(blp:tooltip_unitIconHolder)" }}
			>
				<div
					class="size-5 bg-contain bg-center bg-no-repeat"
					style={{
						"background-image": props.isCivilian
							? "url(blp:action_civilianunits)"
							: "url(blp:tooltip_unitIcon)",
					}}
				/>
			</div>
			<TicketRow icon={unitIcon()}>
				<ProductionTooltip
					category={ProductionPanelCategory.UNITS}
					type={unitTypeString()}
					name={props.unit.name}
					initialVPosition={TooltipVerticalPosition.BOTTOM}
					initialHPosition={TooltipHorizontalPosition.RIGHT}
					allowFlip
				>
					<TooltipKeyword>
						<L10n.Stylize
							class="font-title text-sm break-words pr-4"
							text={props.unit.name}
						/>
					</TooltipKeyword>
				</ProductionTooltip>
				<Show when={props.isMinorOrIndependent}>
					<IndependentUnitInfo
						civName={props.civName}
						relationship={props.relationship}
					/>
				</Show>
				<Show when={!props.isMinorOrIndependent}>
					<PlayerUnitInfo
						unit={props.unit}
						isAtWarWithOwner={props.isAtWarWithOwner}
						ownerName={props.ownerName}
						civName={props.civName}
						relationship={props.relationship}
					/>
				</Show>
			</TicketRow>
		</TicketSection>
	);
};

/** Unit info for independents/minors */
