/** Constructible Rows - handles district header, unique quarter info, and buildings  */
const ConstructibleRows: Component<ConstructibleRowsProps> = (props) => {
	const uniqueQuarterInfo = createMemo(() => {
		if (!props.district?.isUniqueQuarter || props.constructibles.length === 0) return null;

		const uniqueQuarterConstructible = props.constructibles.find(
			(c) => c.uniqueQuarterType != UniqueQuarterTypes.NO_QUARTER,
		);
		if (uniqueQuarterConstructible) {
			return GameInfo.UniqueQuarters.lookup(uniqueQuarterConstructible.uniqueQuarterType);
		}
		return null;
	});

	// Buildings that are part of the unique quarter are rendered inside UniqueQuarterSection,
	// so they must be excluded from the regular constructible list to avoid duplication.
	const uniqueQuarterBuildings = createMemo(() =>
		props.constructibles.filter((c) => c.uniqueQuarterType != UniqueQuarterTypes.NO_QUARTER),
	);
	const otherConstructibles = createMemo(() =>
		uniqueQuarterInfo()
			? props.constructibles.filter((c) => c.uniqueQuarterType == UniqueQuarterTypes.NO_QUARTER)
			: props.constructibles,
	);

	const hasContent = () => props.constructibles.length > 0 || props.freeImprovement != null;

	return (
		<Show when={hasContent()}>
			<Show when={props.constructibles.length > 0}>
				<Show when={uniqueQuarterInfo()}>
					{(info) => (
						<>
							<Show when={props.showTopDivider}>
								<EntryDivider />
							</Show>
							<UniqueQuarterSection
								definition={info()}
								buildings={uniqueQuarterBuildings()}
							/>
						</>
					)}
				</Show>

				<For each={otherConstructibles()}>
					{(constructible, index) => (
						<>
							<Show
								when={index() > 0 || !!uniqueQuarterInfo() || (!!props.showTopDivider && index() === 0)}
							>
								<EntryDivider />
							</Show>
							<ConstructibleRow
								constructible={constructible}
								isLocalPlayer={props.isLocalPlayer}
							/>
						</>
					)}
				</For>
			</Show>

			{/* Free improvement if applicable — shown as a potential/suggested improvement, not a built one */}
			<Show when={props.freeImprovement}>
				{(freeInfo) => (
					<>
						<Show when={props.constructibles.length > 0 || !!uniqueQuarterInfo() || !!props.showTopDivider}>
							<EntryDivider />
						</Show>
						<TicketRow
							icon={
								<Icon
									class="size-10"
									isUrl
									name={freeInfo().icon}
								/>
							}
						>
							<div class="flex flex-col font-body text-sm">
								<L10n.Compose text="LOC_PLOT_TOOLTIP_GROWTH_IMPROVEMENT_PREFIX_ONLY" />
								{/* TODO: Use ProductionTooltip for improvements once descriptions are written */}
								<L10n.Compose text={freeInfo().name} />
							</div>
						</TicketRow>
					</>
				)}
			</Show>
		</Show>
	);
};

/** Combined details ticket showing settlement, owner, resource, constructibles, specialists, route, and plot effects. */
const PlotDetailsSection: Component<PlotDetailsSectionProps> = (props) => {
	const localPlayer = Players.get(GameContext.localObserverID)!;
	const settlementName = createMemo(() => getSettlementName(props.owningCity));
	const ownerInfo = createMemo(() => getOwnerInfo(props.plotCoord, props.owningPlayer));
	const hexResource = createMemo(() => getResource(props.plotCoord));
	const isDistantLands = createMemo(() => localPlayer.isDistantLands(props.plotCoord) ?? false);

	const freeImprovement = createMemo<FreeImprovementInfo | null>(() => {
		if (props.constructibles.length > 0) {
			return null;
		}

		const currentDistrict = props.district;
		if (
			currentDistrict !== null &&
			currentDistrict.type !== DistrictTypes.RURAL &&
			currentDistrict.type !== DistrictTypes.WILDERNESS
		) {
			return null;
		}

		const freeConstructible = Districts.getFreeConstructible(props.plotCoord, GameContext.localPlayerID);
		if (freeConstructible === -1) {
			return null;
		}

		const info = GameInfo.Constructibles.lookup(freeConstructible);
		if (!info) {
			return null;
		}

		return {
			name: info.Name,
			icon: UI.getIconCSS(info.ConstructibleType),
			type: info.ConstructibleType,
		};
	});
	const hasConstructiblesContent = createMemo(() => {
		return props.constructibles.length > 0 || freeImprovement() != null;
	});

	const specialistDesc = createMemo(() => getSpecialistDescription(props.plotCoord, props.owningCity));
	const specialistsAssigned = createMemo(() => {
		const specialist = specialistDesc();
		if (!specialist || specialist.args.length < 2) return null;
		const current = Number(specialist.args[0]);
		const max = Number(specialist.args[1]);
		if (Number.isNaN(current) || Number.isNaN(max) || max <= 0) return null;
		return { current, max };
	});
	// Owner row (and the settlement name nested within it) is only rendered for non-independent owners,
	// so independent ownership should not be treated as content above subsequent sections.
	const hasOwnerRow = createMemo(() => {
		const info = ownerInfo();
		return !!info && !info.isIndependent;
	});
	const hasTopContent = createMemo(() => hasOwnerRow());
	const hasContent = createMemo(() => {
		return hasOwnerRow() || !!hexResource() || hasConstructiblesContent() || !!specialistsAssigned();
	});

	return (
		<Show when={hasContent()}>
			<TicketSection name="PlotDetailsSection">
				<Show when={ownerInfo()}>
					{(info) => (
						<Show when={!info().isIndependent}>
							<PlayerOwnerRow
								playerName={info().playerName}
								civName={info().civName}
								isLocalPlayer={props.owningPlayer === GameContext.localPlayerID}
								playerId={info().suzerainId ?? props.owningPlayer}
								settlementName={settlementName()}
								conquerorInfo={info().conquerorInfo}
							/>
						</Show>
					)}
				</Show>

				<Show when={hexResource()}>
					{(resource) => (
						<>
							<Show when={hasTopContent()}>
								<EntryDivider />
							</Show>
							<ResourceInfoRow
								resource={resource()}
								isDistantLands={isDistantLands()}
							/>
						</>
					)}
				</Show>

				<Show when={hasConstructiblesContent()}>
					<ConstructibleRows
						constructibles={props.constructibles}
						district={props.district}
						freeImprovement={freeImprovement()}
						showTopDivider={hasTopContent() || !!hexResource()}
						isLocalPlayer={props.owningPlayer === GameContext.localPlayerID}
					/>
				</Show>

				<Show when={specialistsAssigned()}>
					{(specialistsAssigned) => (
						<>
							<Show when={hasTopContent() || !!hexResource() || hasConstructiblesContent()}>
								<EntryDivider />
							</Show>
							<SpecialistsRow
								current={specialistsAssigned().current}
								max={specialistsAssigned().max}
							/>
						</>
					)}
				</Show>
			</TicketSection>
		</Show>
	);
};

// ------------------------------ Main Component ------------------------------

/**
 * Plot tooltip content component.
 * Displays detailed information about a world plot including terrain, yields, owner, units, etc.
 */
export const PlotTooltipContent: Component<PlotTooltipContentProps> = (props) => {
	const [local, other] = splitProps(props, ["plotCoord", "showDebug", "class", "owningCity"]);

	const isShowingDebug = createMemo(() => local.showDebug ?? UI.isDebugPlotInfoVisible());
	const currentAge = createMemo(() => getCurrentAge());
	const agelessTypes = createMemo(() => getAgelessTypes());

	// Basic plot data
	const plotIndex = createMemo(() => GameplayMap.getIndexFromLocation(local.plotCoord));
	const terrainLabel = createMemo(() => getTerrainLabel(local.plotCoord, isShowingDebug()));
	const biomeLabel = createMemo(() => getBiomeLabel(local.plotCoord, isShowingDebug()));
	const feature = createMemo(() => getFeatureInfo(local.plotCoord, plotIndex()));
	const continentName = createMemo(() => getContinentName(local.plotCoord));
	const riverLabel = createMemo(() => getRiverLabel(local.plotCoord));
	const playerID = createMemo(() => GameplayMap.getOwner(local.plotCoord.x, local.plotCoord.y));

	const localPlayer = Players.get(GameContext.localObserverID)!;
	const isDistantLands = createMemo(() => localPlayer.isDistantLands(local.plotCoord) ?? false);

	const district = createMemo(() => Districts.getAtLocation(props.plotCoord));
	const overbuildableConstructibles = createMemo(() => district()?.getOverbuildableConstructibleTypes() ?? []);
	// Constructibles
	const constructibles = createMemo(() => {
		const plotConstructibles = MapConstructibles.getHiddenFilteredConstructibles(
			local.plotCoord.x,
			local.plotCoord.y,
		);
		return plotConstructibles
			.map((c) =>
				getConstructibleInfo(c, local.plotCoord, currentAge(), agelessTypes(), overbuildableConstructibles()),
			)
			.filter((c): c is PlotTooltipConstructibleInfo => c != null)
			.sort((a, b) => a.sortOrder - b.sortOrder);
	});
	const hexTreasureResource = createMemo(() => getResource(local.plotCoord));

	// Plot effects
	const plotEffects = createMemo(() => getVisiblePlotEffects(plotIndex()));

	// Unit info
	const unitEntries = createMemo(() => getUnitEntries(local.plotCoord, localPlayer));

	// Terrain type check for lands line
	const terrainType = createMemo(() => GameplayMap.getTerrainType(local.plotCoord.x, local.plotCoord.y));
	const featureType = createMemo(() => GameplayMap.getFeatureType(local.plotCoord.x, local.plotCoord.y));
	const oceanTerrainType = GameInfo.Terrains.find((t) => t.TerrainType === "TERRAIN_OCEAN")?.$index;
	const isOcean = createMemo(() => terrainType() === oceanTerrainType);
	const isMountain = createMemo(() => GameplayMap.isMountain(local.plotCoord.x, local.plotCoord.y));
	const oceanFreeConstructible = createMemo(() => {
		if (!isOcean()) {
			return -1;
		}

		return Districts.getFreeConstructible(local.plotCoord, GameContext.localPlayerID);
	});
	const mountainFreeConstructible = createMemo(() => {
		if (!isMountain()) {
			return -1;
		}

		return Districts.getFreeConstructible(local.plotCoord, GameContext.localPlayerID);
	});
	const shouldShowOceanYields = createMemo(() => {
		if (!isOcean()) {
			return true;
		}

		return constructibles().length > 0 || oceanFreeConstructible() !== -1;
	});
	const shouldShowMountainYields = createMemo(() => {
		if (!isMountain()) {
			return true;
		}

		return constructibles().length > 0 || mountainFreeConstructible() !== -1;
	});
	const featureDefinition = createMemo(() => GameInfo.Features.lookup(featureType()));
	const districtKeyword = createMemo(() => {
		const districtType = district() ? GameInfo.Districts.lookup(district()!.type)?.DistrictType : undefined;
		switch (districtType) {
			case "DISTRICT_CITY_CENTER":
			case "DISTRICT_URBAN":
				return "LOC_PLOT_TOOLTIP_URBAN_DISTRICT";
			case "DISTRICT_RURAL":
				return "LOC_PLOT_TOOLTIP_RURAL_DISTRICT";
			default:
				return undefined;
		}
	});
	const quarterKeyword = createMemo(() => (district()?.isQuarter ? "LOC_PLOT_TOOLTIP_QUARTER" : undefined));

	// Yields
	const yields = createMemo(() => {
		if (!shouldShowOceanYields() || !shouldShowMountainYields()) {
			return [];
		}

		return getPlotYields(local.plotCoord, playerID());
	});
	const yieldBarData = createMemo<YieldBarEntry[]>(() =>
		yields().map((yieldInfo) => ({
			type: yieldInfo.yieldType,
			value: yieldInfo.amount,
			style: YieldBarEntryStyle.NONE,
			iconContext: "YIELD",
		})),
	);
	const totalYields = createMemo(() => yields().reduce((sum, y) => sum + y.amount, 0));

	const keywordPills = createMemo(() => {
		const pills: string[] = [];
		if (feature().label && !feature().isNaturalWonder && !feature().volcano) {
			pills.push(feature().label);
		}

		if ((featureDefinition()?.SightThroughModifier ?? 0) < 0) {
			pills.push("LOC_PLOT_TOOLTIP_BLOCKS_SIGHT");
		}
		if ((featureDefinition()?.MovementChange ?? 0) < 0) {
			pills.push("LOC_PLOT_TOOLTIP_ENDS_MOVEMENT");
		}
		if (districtKeyword()) {
			pills.push(districtKeyword()!);
		}
		if (quarterKeyword()) {
			pills.push(quarterKeyword()!);
		}
		return pills;
	});
	const route = createMemo(() => getRouteData(local.plotCoord));

	// Debug info
	const debugHealthInfo = createMemo(() => {
		const ph = Players.Districts.get(playerID())?.getDistrictHealth(local.plotCoord);
		const mh = Players.Districts.get(playerID())?.getDistrictMaxHealth(local.plotCoord);
		return { current: ph, max: mh };
	});

	// First line text (terrain with optional biome)
	const firstLineText = createMemo(() => {
		if (biomeLabel()) {
			return "LOC_PLOT_TOOLTIP_TERRAIN_WITH_BIOME";
		}
		return terrainLabel();
	});
	const firstLineArgs = createMemo((): LocalizedTextArgument[] => {
		if (biomeLabel()) {
			return [terrainLabel(), biomeLabel()];
		}
		return [];
	});

	// Third line (continent and/or river and homelands)
	const landsLabel = createMemo(() =>
		!isOcean() ? (isDistantLands() ? "LOC_PLOT_TOOLTIP_HEMISPHERE_WEST" : "LOC_PLOT_TOOLTIP_HEMISPHERE_EAST") : "",
	);
	const subheaderText = createMemo(() => {
		const parts: string[] = [];
		if (riverLabel()) parts.push(riverLabel());
		if (continentName()) parts.push(continentName());
		if (landsLabel()) parts.push(landsLabel());
		return parts.map((part) => Locale.compose(part)).join(", ");
	});

	return (
		<div
			class={`w-auto min-w-62 max-w-84 self-start text-sm ${local.class ?? ""}`}
			{...other}
		>
			{/* Terrain/Biome Line */}
			<Show
				when={biomeLabel()}
				fallback={
					<L10n.Stylize
						class="text-secondary text-center uppercase font-title"
						text={terrainLabel()}
					/>
				}
			>
				<L10n.Stylize
					class="text-secondary text-center uppercase font-title"
					text={firstLineText()}
					args={firstLineArgs()}
				/>
			</Show>

			{/* Continent/River/Homelands Line */}
			<Show when={subheaderText()}>
				<div class="relative">
					<L10n.Stylize
						class="text-sm text-center"
						style={{ "line-height": "1rem" }}
						text={subheaderText()}
					/>

					{/* <div
					class="absolute -left-2\.5 w-24 h-6 bg-no-repeat bg-contain"
					style={{ "background-image": "url(blp:wip_label)" }}
					/> */}
				</div>
			</Show>

			{/* Keywords */}
			<Show when={keywordPills().length > 0 || route()}>
				<div class="flex flex-row flex-wrap justify-center mt-1 gap-2">
					<For each={keywordPills()}>
						{(keyword) => (
							<PillText
								text={keyword}
								small
							/>
						)}
					</For>
					<Show when={route()}>
						{(route) => (
							<Pill
								class="text-sm"
								small
							>
								<Icon
									class="size-5 mr-1"
									name={route().type}
								/>
								<L10n.Stylize text={route().name} />
							</Pill>
						)}
					</Show>
				</div>
			</Show>

			<PlotAlertSection
				plotCoord={local.plotCoord}
				plotIndex={plotIndex()}
				feature={feature()}
				plotEffects={plotEffects()}
				constructibles={constructibles()}
				unitEntries={unitEntries()}
			/>

			<Show
				when={
					hexTreasureResource()?.ResourceClassType === "RESOURCECLASS_TREASURE" &&
					local.owningCity != null &&
					isDistantLands()
				}
			>
				<TreasureConvoySection
					owningCity={local.owningCity}
					isDistantLands={isDistantLands()}
				/>
			</Show>

			<Show when={feature().volcano}>{(volcano) => <VolcanoSection volcano={volcano()} />}</Show>

			<Show when={feature().isNaturalWonder}>
				<TicketSection name="NaturalWonderSection">
					<TicketRow
						icon={
							<Icon
								class="size-8"
								name={"url(blp:generic_natural_wonder)"}
								isUrl
							/>
						}
					>
						<L10n.Stylize
							class="font-title text-sm uppercase text-secondary"
							text={feature().label}
						/>
						<L10n.Stylize
							class="font-body text-sm"
							text={"LOC_PLOT_TOOLTIP_NATURAL_WONDER"}
						/>
						<L10n.Stylize
							class="font-body text-sm"
							text={feature().tooltip}
						/>
					</TicketRow>
				</TicketSection>
			</Show>
			<PlotDetailsSection
				plotCoord={local.plotCoord}
				owningPlayer={playerID()}
				owningCity={local.owningCity}
				constructibles={constructibles()}
				district={district()}
			/>

			<For each={unitEntries()}>{(info) => <UnitInfoSection {...info} />}</For>

			<Show when={yieldBarData().length > 0}>
				<YieldBar
					yieldBarData={yieldBarData()}
					variant="compact"
					class="grow flex-wrap justify-center mt-1"
				/>
				<Show when={totalYields() > 0}>
					<L10n.Stylize
						class="text-center"
						text="LOC_PLOT_TOTAL_YIELDS"
						args={[Locale.toNumber(totalYields(), "0.0")]}
					/>
				</Show>
			</Show>

			{/* Debug Info */}
			<Show when={isShowingDebug()}>
				<DebugInfoSection
					plotCoord={local.plotCoord}
					plotIndex={plotIndex()}
					currentHealth={debugHealthInfo().current}
					maxHealth={debugHealthInfo().max}
				/>
			</Show>
		</div>
	);
};

// ------------------------------ Full Tooltip Component ------------------------------

/** Props for the PlotTooltip component */
export interface PlotTooltipProps extends Omit<TooltipBaseProps, "children"> {
	/** Whether to show debug information in the tooltip. @default false */
	showDebug?: boolean;
}

/** The type of specialized content to display in the plot tooltip. */
type PlotTooltipKind = "settlement-recommendation" | "random-event" | "archeology" | "default";

/**
 * Determines which specialized plot tooltip content should be shown for the given plot coordinates.
 * Mirrors the priority-based resolution from the legacy tooltip manager:
 *   1. Settlement recommendation (settler lens, gamepad active, has data)
 *   2. Random event (settler lens, has data)
 *   3. Archeology (continent lens, gamepad active, has data)
 *   4. Default plot tooltip (fallback)
 */
function getPlotTooltipKind(plotCoord: float2): PlotTooltipKind {
	const activeLens = LensManager.getActiveLens();

	if (activeLens === "fxs-settler-lens") {
		if (hasSettlementRecommendationData(plotCoord)) {
			return "settlement-recommendation";
		}
		if (hasRandomEventData(plotCoord)) {
			return "random-event";
		}
	}

	if (activeLens === "fxs-continent-lens" && hasArcheologyData(plotCoord)) {
		return "archeology";
	}

	return "default";
}

/**
 * A complete plot tooltip component that displays information about the hovered world plot.
 * Automatically tracks plot cursor position and shows/hides based on plot visibility.
 *
 * @example
 * ```tsx
 * <PlotTooltip />
 * ```
 */
const PlotTooltipComponent: Component<PlotTooltipProps> = (props) => {
	const [local, other] = splitProps(props, ["showDebug", "class"]);
	const [plotCoords, setPlotCoords] = createSignal<PlotCoord>();
	const owningCity = createMemo(() => {
		const coord = plotCoords();
		if (!coord) return null;
		const cityId = GameplayMap.getOwningCityFromXY(coord.x, coord.y);
		return cityId ? Cities.get(cityId) : null;
	});

	return (
		<Tooltip
			initialVPosition={TooltipVerticalPosition.BOTTOM}
			initialHPosition={TooltipHorizontalPosition.RIGHT}
			offset={22}
			allowFlip={true}
			{...other}
		>
			{/* @ts-expect-error -- Solid.js Typing issue */}
			{() => {
				const tooltipModel = TooltipModel.get();
				const focusManager = FocusManager.get();

				const parentContext = useContext(TriggerActivationContext);
				const tooltipContext = useContext(TooltipContext);
				if (!tooltipContext) {
					throw new Error("PlotTooltipTrigger must be used within a <Tooltip> root component");
				}

				let isPanning = false;
				const [showTouchPressPlotTooltip, setShowTouchPressPlotTooltip] = createSignal(false);
				const [isWorldDragging, setIsWorldDragging] = createSignal(false);
				const triggerContext = new TriggerActivationContextProvider(
					tooltipModel,
					parentContext,
					() => tooltipContext.name,
				);
				tooltipContext.setTriggerContext(triggerContext);

				let tooltipDelayHandle: number | undefined;

				const clearTooltipDelay = () => {
					if (tooltipDelayHandle !== undefined) {
						clearTimeout(tooltipDelayHandle);
						tooltipDelayHandle = undefined;
					}
				};
				const hidePlotTooltip = () => {
					if (tooltipModel.isLocked(tooltipContext.name)) {
						return;
					}

					clearTooltipDelay();
					tooltipModel.triggerTooltip(tooltipContext.name, TriggerType.Blur, undefined);
				};

				const triggerWithDelay = (plotCoords: PlotCoord) => {
					clearTooltipDelay();
					const activeTooltips = tooltipModel.active();
					// only apply delay to the first tooltip, but not nested tooltips
					const delay = activeTooltips.length === 0 ? Configuration.getUser().plotTooltipDelay : 0;
					if (delay <= 0) {
						tooltipModel.triggerTooltip(tooltipContext.name, TriggerType.Focus, plotCoords);
						return;
					}
					tooltipDelayHandle = window.setTimeout(() => {
						tooltipDelayHandle = undefined;
						tooltipModel.triggerTooltip(tooltipContext.name, TriggerType.Focus, plotCoords);
					}, delay);
				};

				const trySetPlotCoords = (incomingPlotCoords: PlotCoord | undefined) => {
					const currentPlotCoord = plotCoords();
					if (
						incomingPlotCoords?.x === currentPlotCoord?.x &&
						incomingPlotCoords?.y === currentPlotCoord?.y
					) {
						return;
					}

					if (tooltipModel.isLocked(tooltipContext.name)) {
						return;
					}
					setPlotCoords(incomingPlotCoords);
				};

				const onCursorUpdated = (event: CursorUpdatedEvent) => {
					trySetPlotCoords(event.detail.plot ?? undefined);
				};

				const onPlotCursorCoordsUpdated = (event: PlotCursorUpdatedEvent) => {
					trySetPlotCoords(event.detail.plotCoords ?? undefined);
				};

				let cameraChangeTimeout: number | undefined;
				let prevCameraState: CameraState | null = null;
				const onCameraChanged = (nextCameraState: CameraState) => {
					if (
						nextCameraState.focusPoint.x === prevCameraState?.focusPoint.x &&
						nextCameraState.focusPoint.y === prevCameraState?.focusPoint.y
					) {
						prevCameraState = nextCameraState;
						return;
					}
					prevCameraState = nextCameraState;
					setIsWorldDragging(true);
					isPanning = true;

					if (cameraChangeTimeout !== undefined) {
						clearTimeout(cameraChangeTimeout);
					}

					cameraChangeTimeout = window.setTimeout(() => {
						setIsWorldDragging(false);
					}, 50);
				};

				const onInputAction = (name: string, status: InputActionStatuses) => {
					if (IsTouchActive() && status == InputActionStatuses.FINISH) {
						if (name === "touch-press") {
							if (!isPanning) {
								setShowTouchPressPlotTooltip(true);
							}
						} else if (name === "touch-tap") {
							setShowTouchPressPlotTooltip(false);
						} else if (name == "touch-complete") {
							isPanning = false;
						}
					}
				};

				const isRevealed = createMemo(() => {
					const currentPlotCoords = plotCoords();
					if (!currentPlotCoords) return false;

					const revealedState = GameplayMap.getRevealedState(
						GameContext.localPlayerID,
						currentPlotCoords.x,
						currentPlotCoords.y,
					);
					return revealedState !== RevealedStates.HIDDEN;
				});

				const isWorldFocused = createMemo(() => {
					return focusManager.activeElement() === document.body;
				});

				// combine all visibility conditions here so that the tooltip is properly shown/hidden as soon as any relevant state changes
				createEffect(
					on(
						[
							plotCoords,
							IsPlotTooltipVisible,
							isWorldFocused,
							isRevealed,
							isWorldDragging,
							showTouchPressPlotTooltip,
						],
						(
							[
								currentPlotCoords,
								isVisible,
								currentIsWorldFocused,
								revealed,
								currentIsWorldDragging,
								pressingShowTouchPlotTooltip,
							],
							prevValues,
						) => {
							const [
								prevPlotCoords,
								_prevIsVisible,
								_prevIsWorldFocused,
								_prevRevealed,
								prevIsWorldDragging,
								_prevPressingShowTouchPlotTooltip,
							] = prevValues ?? [];
							if (
								!currentPlotCoords ||
								!isVisible ||
								!currentIsWorldFocused ||
								!revealed ||
								currentIsWorldDragging ||
								(!pressingShowTouchPlotTooltip && IsTouchActive())
							) {
								hidePlotTooltip();
								// don't re-enable the tooltip if we just stopped dragging
							} else if (!currentIsWorldDragging && !prevIsWorldDragging) {
								if (
									currentPlotCoords.x !== prevPlotCoords?.x ||
									currentPlotCoords.y !== prevPlotCoords?.y
								) {
									// blur so we respect the tooltip delay on every new plot, even if the tooltip is already shown
									tooltipModel.triggerTooltip(tooltipContext.name, TriggerType.Blur, undefined);
								}

								triggerWithDelay(currentPlotCoords);
							}
						},
					),
				);

				createEffect(() => {
					if (IsMouseActive()) {
						window.addEventListener("cursor-updated", onCursorUpdated);
						onCleanup(() => {
							window.removeEventListener("cursor-updated", onCursorUpdated);
						});
					} else {
						window.addEventListener("plot-cursor-coords-updated", onPlotCursorCoordsUpdated);
						onCleanup(() => {
							window.removeEventListener("plot-cursor-coords-updated", onPlotCursorCoordsUpdated);
						});
					}
				});

				onMount(() => {
					engine.on("CameraChanged", onCameraChanged);
					engine.on("InputAction", onInputAction);

					onCleanup(() => {
						clearTooltipDelay();
						window.removeEventListener("cursor-updated", onCursorUpdated);
						window.removeEventListener("plot-cursor-coords-updated", onPlotCursorCoordsUpdated);
						engine.off("CameraChanged", onCameraChanged);
						engine.off("InputAction", onInputAction);
					});
				});

				return (
					<TriggerActivationContext.Provider value={triggerContext}>
						<Tooltip.Content class={local.class}>
							<Show when={plotCoords()}>
								{(currentPlotCoords) => {
									const tooltipKind = createMemo(() => getPlotTooltipKind(currentPlotCoords()));
									return (
										<Tooltip.Frame class="relative flex flex-col">
											<Switch
												fallback={
													<PlotTooltipContent
														plotCoord={currentPlotCoords()}
														showDebug={local.showDebug}
														owningCity={owningCity()}
													/>
												}
											>
												<Match when={tooltipKind() === "settlement-recommendation"}>
													<SettlementRecommendationPlotTooltipContent
														plotCoord={currentPlotCoords()}
														showDebug={local.showDebug}
														owningCity={owningCity()}
													/>
												</Match>
												<Match when={tooltipKind() === "random-event"}>
													<RandomEventPlotTooltipContent
														plotCoord={currentPlotCoords()}
														showDebug={local.showDebug}
														owningCity={owningCity()}
													/>
												</Match>
												<Match when={tooltipKind() === "archeology"}>
													<ArcheologyPlotTooltipContent
														plotCoord={currentPlotCoords()}
														showDebug={local.showDebug}
														owningCity={owningCity()}
													/>
												</Match>
											</Switch>
										</Tooltip.Frame>
									);
								}}
							</Show>
						</Tooltip.Content>
					</TriggerActivationContext.Provider>
				);
			}}
		</Tooltip>
	);
};

/**
 * A complete plot tooltip component that displays information about the hovered world plot.
 * Automatically tracks plot cursor position and shows/hides based on plot visibility.
 *
 * @example
 * ```tsx
 * <PlotTooltip />
 * ```
 */
export const PlotTooltip = ComponentRegistry.register({
	name: "PlotTooltip",
	createInstance: PlotTooltipComponent,
});
